code_files.file:
{lix, ...} @ base:
lix.importModules (base
  // {
    base = ./.;
    recurse = false;
    excludes = [
      "applications"
      "services"
      "secrets"
      "displays"
      "test"
    ];
  })

{
  lix,
  top,
  host,
  path,
  ...
} @ args: let
  inherit (lix.attrsets) hasAttrByPath mapAttrs optionalAttrs recursiveUpdate setAttrByPath;
  inherit (lix.lists) findFirst;
  inherit (lix.modules) mkIf mkMerge mkModules;
  inherit (lix.options) mkEnableOption mkModuleArgs mkOption;
  inherit (lix.types) enum nullOr package str submodule;

  here = path;

  mkMod = {
    config,
    osConfig ? config,
    options ? {},
    scope ? "core",
    pkgs,
    path ? here,
    defaults ? {},
  }: let
    args = mkModuleArgs {
      lib = lix;
      inherit
        config
        defaults
        host
        options
        osConfig
        path
        pkgs
        scope
        top
        ;
    };
    inherit (args) get set;
    inherit (get) prettyName name cfg cfgOr apiOr;
    inherit (set) opt bin;

    default = let
      derived = {
        enable = apiOr "enable";
        protocol = apiOr "protocol";
        uwsm = apiOr "uwsm";
        session = apiOr "session";
        needsXwaylandSatellite = apiOr "needsXwaylandSatellite";
        frontend = apiOr "frontend";
        greeter = apiOr "greeter";
        package = apiOr "package";
      };

      updated =
        mapAttrs
        (
          key: value: let
            derivedValue = derived.${key} or null;
          in
            if derivedValue != null
            then derivedValue
            else value
        )
        (
          recursiveUpdate {
            enable = false;
            protocol = null;
            uwsm = null;
            session = name;
            needsXwaylandSatellite = false;
            frontend = null;
            greeter = null;
            package = get.package;
          }
          defaults
        );
    in
      updated
      // {
        uwsm =
          if derived.uwsm != null
          then derived.uwsm
          else updated.protocol == "wayland" && updated.enable;
      };

    fields =
      {
        enable = set.enable {default = default.enable;};

        package = mkOption {
          type = nullOr package;
          default = default.package;
          description = "Package backing the ${prettyName} compositor component.";
        };

        protocol = mkOption {
          type = nullOr (enum ["x11" "wayland"]);
          default = default.protocol;
          description = "Display protocol for ${prettyName}. Defaults to the backend registry or host/user override.";
        };

        session = mkOption {
          type = nullOr str;
          default = default.session;
          description = "Session name exported by ${prettyName}. Defaults to the backend registry or host/user override.";
        };

        greeter = mkOption {
          type = nullOr str;
          default = default.greeter;
          description = "Greeter or display manager preferred for ${prettyName}. Defaults to the backend registry or host/user override.";
        };

        frontend = mkOption {
          type = nullOr str;
          default = default.frontend;
          description = "Frontend layer paired with ${prettyName}. Defaults to the backend registry or host/user override.";
        };

        needsXwaylandSatellite =
          mkEnableOption "xwayland-satellite support for ${prettyName}"
          // {default = default.needsXwaylandSatellite;};
      }
      // optionalAttrs (scope == "core") {
        uwsm = mkOption {
          description = "UWSM configuration for ${prettyName}. Set to `null` to disable UWSM integration.";
          type = submodule {
            options = {
              enable = mkEnableOption "${prettyName} UWSM support." // {default = default.uwsm;};
              name = mkOption {
                type = str;
                description = "Human-readable name shown by UWSM.";
                default = prettyName;
              };
              description = mkOption {
                type = str;
                description = "Comment shown by UWSM.";
                default = "${prettyName} compositor managed by UWSM";
              };
              binary = mkOption {
                type = str;
                description = "Absolute path to the compositor binary.";
                default = (bin {}).path;
              };
            };
          };
        };
      };

    target = findFirst (candidate: hasAttrByPath candidate options) null [
      ["wayland" "windowManager" name]
      ["programs" name]
    ];
    hasSub = key: target != null && hasAttrByPath (target ++ [key]) options;
    initiated = args // {inherit fields cfgOr;};
    evaluated = {
      options = opt fields;
      config =
        if scope == "home"
        then
          optionalAttrs (target != null) (setAttrByPath target (
            optionalAttrs (hasSub "enable") {enable = cfg.enable;}
            // optionalAttrs (hasSub "package") {inherit (cfg) package;}
          ))
        else
          mkMerge [
            (mkIf (cfg.enable or false) (
              optionalAttrs
              (hasSub "enable")
              (setAttrByPath (target ++ ["enable"]) cfg.enable)
            ))
            (mkIf (cfg.enable or false) (
              optionalAttrs
              (hasSub "package")
              (setAttrByPath (target ++ ["package"]) cfg.package)
            ))
            (mkIf ((cfg.enable or false)
              && cfg.protocol == "wayland"
              && (cfg.uwsm.enable or false)) {
              programs.uwsm = {
                enable = true;
                waylandCompositors.${name} = {
                  prettyName = cfg.uwsm.name;
                  comment = cfg.uwsm.description;
                  binPath = cfg.uwsm.binary;
                };
              };
            })
          ];
    };
  in
    initiated // {inherit initiated evaluated;};

  inner = mkModules (args
    // {
      base = ./.;
      declareRegistry = true;
      childPath = path;
      extraArgs = {
        mkArgs = {
          config,
          options ? {},
          path,
          pkgs ? {},
          scope ? "core",
          osConfig ? {},
          defaults ? {},
        }:
          mkMod {inherit config defaults options osConfig path pkgs scope;};
      };
    });
in {
  core.imports = inner.imports or [];
  home.imports = inner.home-manager.sharedModules or [];
}

{
  lix,
  path,
  mkArgs,
  ...
}: let
  inherit (lix.attrsets) recursiveUpdate;
  inherit (lix.modules) mkMerge mkIf;
  inherit (lix.options) mkOption;
  inherit (lix.types) enum;

  mk = scope: {
    config,
    options,
    pkgs,
    osConfig ? {},
    ...
  }: let
    inherit (mkArgs {inherit config options osConfig path pkgs scope;}) evaluated get set;
    inherit (get) apiOr cfg name;
    inherit (set) opt;
  in {
    options =
      recursiveUpdate
      evaluated.options
      (opt {
        configType = mkOption {
          type = enum ["hyprlang" "lua"];
          default = let
            derived = apiOr "configType";
            default = "hyprlang";
          in
            if derived != null
            then derived
            else default;
          description = "Home Manager Hyprland configuration format.";
        };
        test = mkOption {
          default = get.dataEntry or null;
          description = "Home Manager Hyprland configuration format.";
        };
      });

    config = mkMerge [
      evaluated.config
      (mkIf (cfg.enable or false) (
        if scope == "core"
        then {programs.${name} = {withUWSM = cfg.uwsm.enable;};}
        else {wayland.windowManager.${name}.configType = cfg.configType;}
      ))
    ];
  };
in {
  core = mk "core";
  home = mk "home";
}

{
  path,
  mkArgs,
  ...
}: let
  mk = args: mkArgs ({inherit path;} // args);
in {
  core = {
    config,
    options,
    pkgs,
    ...
  }:
    (mk {
      inherit config options pkgs;
      scope = "core";
    }).evaluated;

  home = {
    config,
    options,
    pkgs,
    ...
  }:
    (mk {
      inherit config options pkgs;
      scope = "home";
    }).evaluated;
}

{
  lix,
  path,
  mkArgs,
  ...
}: let
  inherit (lix.attrsets) genAttrs recursiveUpdate;
  inherit (lix.options) mkOption;
  inherit (lix.types) str;

  mk = args: mkArgs ({inherit path;} // args);
  defaults = {
    fallbackConfig = "config/niri/config.kdl";
  };

  mkOptions = overrides: {
    fallbackConfig = mkOption {
      type = str;
      default = let
        derived = overrides.fallbackConfig or null;
        default = defaults.fallbackConfig or "";
      in
        if derived != null
        then derived
        else default;
      description = "Path to Niri fallback KDL configuration.";
    };
  };
in {
  core = {
    config,
    options,
    pkgs,
    ...
  }: let
    inherit (mk {inherit config options pkgs defaults;}) apiOr set evaluated;
  in {
    imports = [./options.nix];
    options =
      recursiveUpdate
      evaluated.options
      (set.options.module (mkOptions (genAttrs ["fallbackConfig"] apiOr)));
    inherit (evaluated) config;
  };

  home = {
    config,
    options,
    pkgs,
    osConfig,
    ...
  }: let
    scope = "home";
    mod = mk {inherit config options osConfig pkgs scope defaults;};
    inherit (mod) apiOr set evaluated;
  in {
    imports = [
      ./keybinds.nix
      ./options.nix
      ./packages.nix
    ];
    options =
      recursiveUpdate
      evaluated.options
      (set.options.module (mkOptions (genAttrs ["fallbackConfig"] apiOr)));
    inherit (evaluated) config;
  };
}

{
  config,
  lix,
  options,
  top,
  ...
}: let
  inherit (lix.attrsets) filterAttrs optionalAttrs;
  inherit (lix.modules) mkIf;

  cfg = config.${top}.interface.backends.niri;
  hasNiriProgram = options.programs ? niri;

  # Check standard options directly instead of taking them as arguments
  enable = cfg.enable or false;
  semanticKeybinds = cfg.semanticKeybinds or false;
  actions = cfg.actions or {};

  enabled = filterAttrs (_: action: action.command != null) actions;

  spawn = command: {action.spawn = ["sh" "-lc" command];};

  withTitle = key: title: action: {
    ${key} =
      (spawn action.command)
      // {hotkey-overlay.title = title;};
  };

  defaults = {
    "Mod+Shift+Slash" = {action.show-hotkey-overlay = [];};

    "Mod+Left" = {action.focus-column-left = [];};
    "Mod+Right" = {action.focus-column-right = [];};
    "Mod+Up" = {action.focus-window-up = [];};
    "Mod+Down" = {action.focus-window-down = [];};
    "Mod+H" = {action.focus-column-left = [];};
    "Mod+L" = {action.focus-column-right = [];};
    "Mod+K" = {action.focus-window-up = [];};
    "Mod+J" = {action.focus-window-down = [];};

    "Mod+Ctrl+Left" = {action.focus-monitor-left = [];};
    "Mod+Ctrl+Right" = {action.focus-monitor-right = [];};
    "Mod+Ctrl+Up" = {action.focus-monitor-up = [];};
    "Mod+Ctrl+Down" = {action.focus-monitor-down = [];};
    "Mod+Ctrl+H" = {action.focus-monitor-left = [];};
    "Mod+Ctrl+L" = {action.focus-monitor-right = [];};
    "Mod+Ctrl+K" = {action.focus-monitor-up = [];};
    "Mod+Ctrl+J" = {action.focus-monitor-down = [];};

    "Mod+Shift+Left" = {action.move-column-left = [];};
    "Mod+Shift+Right" = {action.move-column-right = [];};
    "Mod+Shift+Up" = {action.move-window-up = [];};
    "Mod+Shift+Down" = {action.move-window-down = [];};
    "Mod+Shift+H" = {action.move-column-left = [];};
    "Mod+Shift+L" = {action.move-column-right = [];};
    "Mod+Shift+K" = {action.move-window-up = [];};
    "Mod+Shift+J" = {action.move-window-down = [];};

    "Mod+Ctrl+Shift+Left" = {action.move-column-to-monitor-left = [];};
    "Mod+Ctrl+Shift+Right" = {action.move-column-to-monitor-right = [];};
    "Mod+Ctrl+Shift+Up" = {action.move-column-to-monitor-up = [];};
    "Mod+Ctrl+Shift+Down" = {action.move-column-to-monitor-down = [];};
    "Mod+Ctrl+Shift+H" = {action.move-column-to-monitor-left = [];};
    "Mod+Ctrl+Shift+L" = {action.move-column-to-monitor-right = [];};
    "Mod+Ctrl+Shift+K" = {action.move-column-to-monitor-up = [];};
    "Mod+Ctrl+Shift+J" = {action.move-column-to-monitor-down = [];};

    "Mod+R" = {action.switch-preset-column-width = [];};
    "Mod+Shift+R" = {action.switch-preset-window-height = [];};
    "Mod+Ctrl+R" = {action.reset-window-height = [];};
    "Mod+Minus" = {action.set-column-width = "-10%";};
    "Mod+Equal" = {action.set-column-width = "+10%";};
    "Mod+Shift+Minus" = {action.set-window-height = "-10%";};
    "Mod+Shift+Equal" = {action.set-window-height = "+10%";};
    "Mod+I" = {action.expand-column-to-available-width = [];};

    "Mod+Shift+F" = {action.fullscreen-window = [];};
    "Mod+Shift+C" = {action.center-column = [];};

    "Mod+Comma" = {action.consume-window-into-column = [];};
    "Mod+Period" = {action.expel-window-from-column = [];};
    "Mod+BracketLeft" = {action.consume-or-expel-window-left = [];};
    "Mod+BracketRight" = {action.consume-or-expel-window-right = [];};

    "Mod+Tab" = {action.toggle-overview = [];};

    "Mod+Page_Down" = {action.focus-workspace-down = [];};
    "Mod+Page_Up" = {action.focus-workspace-up = [];};
    "Mod+U" = {action.focus-workspace-down = [];};
    "Mod+Shift+Page_Down" = {action.move-column-to-workspace-down = [];};
    "Mod+Shift+Page_Up" = {action.move-column-to-workspace-up = [];};
    "Mod+Shift+U" = {action.move-column-to-workspace-down = [];};
    "Mod+Shift+I" = {action.move-column-to-workspace-up = [];};

    "Mod+1" = {action.focus-workspace = 1;};
    "Mod+2" = {action.focus-workspace = 2;};
    "Mod+3" = {action.focus-workspace = 3;};
    "Mod+4" = {action.focus-workspace = 4;};
    "Mod+5" = {action.focus-workspace = 5;};
    "Mod+6" = {action.focus-workspace = 6;};
    "Mod+7" = {action.focus-workspace = 7;};
    "Mod+8" = {action.focus-workspace = 8;};
    "Mod+9" = {action.focus-workspace = 9;};

    "Mod+Shift+1" = {action.move-column-to-workspace = 1;};
    "Mod+Shift+2" = {action.move-column-to-workspace = 2;};
    "Mod+Shift+3" = {action.move-column-to-workspace = 3;};
    "Mod+Shift+4" = {action.move-column-to-workspace = 4;};
    "Mod+Shift+5" = {action.move-column-to-workspace = 5;};
    "Mod+Shift+6" = {action.move-column-to-workspace = 6;};
    "Mod+Shift+7" = {action.move-column-to-workspace = 7;};
    "Mod+Shift+8" = {action.move-column-to-workspace = 8;};
    "Mod+Shift+9" = {action.move-column-to-workspace = 9;};

    "Mod+WheelScrollDown" = {
      action.focus-workspace-down = [];
      cooldown-ms = 150;
    };
    "Mod+WheelScrollUp" = {
      action.focus-workspace-up = [];
      cooldown-ms = 150;
    };
    "Mod+WheelScrollRight" = {action.focus-column-right = [];};
    "Mod+WheelScrollLeft" = {action.focus-column-left = [];};
    "Mod+Shift+WheelScrollDown" = {
      action.focus-column-right = [];
      cooldown-ms = 150;
    };
    "Mod+Shift+WheelScrollUp" = {
      action.focus-column-left = [];
      cooldown-ms = 150;
    };

    "Print" = {action.screenshot = [];};
    "Ctrl+Print" = {action.screenshot-screen = [];};
    "Alt+Print" = {action.screenshot-window = [];};

    "XF86AudioRaiseVolume" = {
      action.spawn = ["wpctl" "set-volume" "@DEFAULT_AUDIO_SINK@" "0.1+"];
      allow-when-locked = true;
    };
    "XF86AudioLowerVolume" = {
      action.spawn = ["wpctl" "set-volume" "@DEFAULT_AUDIO_SINK@" "0.1-"];
      allow-when-locked = true;
    };
    "XF86AudioMute" = {
      action.spawn = ["wpctl" "set-mute" "@DEFAULT_AUDIO_SINK@" "toggle"];
      allow-when-locked = true;
    };
    "XF86AudioMicMute" = {
      action.spawn = ["wpctl" "set-mute" "@DEFAULT_AUDIO_SOURCE@" "toggle"];
      allow-when-locked = true;
    };
    "XF86MonBrightnessUp" = {action.spawn = ["brightnessctl" "set" "10%+"];};
    "XF86MonBrightnessDown" = {action.spawn = ["brightnessctl" "set" "10%-"];};

    "Mod+Escape" = {action.toggle-keyboard-shortcuts-inhibit = [];};
  };
in {
  config = mkIf (hasNiriProgram && enable && semanticKeybinds) {
    programs.niri.settings.binds =
      defaults
      // optionalAttrs (enabled ? secondaryLauncher)
      (withTitle "Mod+Space" "Open Fuzzel" enabled.secondaryLauncher)
      // optionalAttrs (enabled ? terminal)
      (withTitle "Mod+Return" "Open terminal" enabled.terminal)
      // optionalAttrs (enabled ? scratchpadTerminal)
      (withTitle "Mod+Grave" "Open scratchpad terminal" enabled.scratchpadTerminal)
      // optionalAttrs (enabled ? primaryBrowser)
      (withTitle "Mod+B" "Open primary browser" enabled.primaryBrowser)
      // optionalAttrs (enabled ? secondaryBrowser)
      (withTitle "Mod+Alt+B" "Open secondary browser" enabled.secondaryBrowser)
      // optionalAttrs (enabled ? visualTools)
      (withTitle "Mod+V" "Open visual tools" enabled.visualTools)
      // optionalAttrs (enabled ? fileManager)
      (withTitle "Mod+F" "Open file manager" enabled.fileManager)
      // optionalAttrs (enabled ? editor)
      (withTitle "Mod+E" "Open editor" enabled.editor)
      // optionalAttrs (actions.fullscreen.description != null) {
        "Alt+Return" = {
          action.fullscreen-window = [];
          hotkey-overlay.title = "Toggle fullscreen";
        };
        "Mod+Ctrl+F" = {
          action.fullscreen-window = [];
          hotkey-overlay.title = "Toggle fullscreen";
        };
      }
      // optionalAttrs (actions.logout.description != null) {
        "Mod+Ctrl+Q" = {
          action.quit.skip-confirmation = true;
          hotkey-overlay.title = "Exit niri";
        };
      }
      // optionalAttrs (actions.closeWindow.description != null) {
        "Mod+Q" = {
          action.close-window = [];
          hotkey-overlay.title = "Close focused window";
        };
      }
      // optionalAttrs (enabled ? lock)
      (withTitle "Mod+Ctrl+L" "Lock session" enabled.lock)
      // optionalAttrs (actions.showKeybinds.description != null) {
        "Mod+Ctrl+Slash" = {
          action.show-hotkey-overlay = [];
          hotkey-overlay.title = "Show common keybinds";
        };
      }
      // optionalAttrs (enabled ? screenshot) {
        "Mod+Print" = {
          action.spawn = ["sh" "-lc" enabled.screenshot.command];
          hotkey-overlay.title = "Region screenshot → clipboard";
        };
      };
  };
}

{
  lib,
  top,
  ...
}: let
  cfgPath = [top "interface" "backends" "niri"];

  inherit (lib.attrsets) setAttrByPath;
  inherit (lib.options) mkEnableOption mkOption;
  inherit (lib.types) nullOr str submodule;

  mkActionOption = description: defaults:
    mkOption {
      type = submodule {
        options = {
          command = mkOption {
            type = nullOr str;
            default = defaults.command or null;
            description = "Shell command for the ${description} action.";
          };
          description = mkOption {
            type = str;
            default = defaults.description or description;
            description = "Human-readable label for the ${description} action.";
          };
        };
      };
      default = {};
      description = "Shared semantic Niri action for ${description}.";
    };
in {
  options = setAttrByPath cfgPath {
    modifier = mkOption {
      type = str;
      default = "SUPER";
      description = ''
        Primary compositor modifier key. Niri binds use its compositor-agnostic
        `Mod` alias, but this keeps the chosen host intent visible in the live API.
      '';
    };

    semanticKeybinds =
      mkEnableOption "modular semantic keybind layer for Niri"
      // {default = true;};

    actions = {
      secondaryLauncher = mkActionOption "secondary launcher" {
        command = "fuzzel";
        description = "Open Fuzzel";
      };
      showKeybinds = mkActionOption "show keybinds/help" {
        command = "dots-common-keybinds";
        description = "Show common keybinds";
      };
      terminal = mkActionOption "terminal" {
        command = "foot";
        description = "Open terminal";
      };
      scratchpadTerminal = mkActionOption "scratchpad/quake terminal" {
        command = "foot --app-id dots-scratchpad";
        description = "Open scratchpad terminal";
      };
      primaryBrowser = mkActionOption "primary browser" {
        command = "zen";
        description = "Open primary browser";
      };
      secondaryBrowser = mkActionOption "secondary browser" {
        command = "chromium";
        description = "Open secondary browser";
      };
      visualTools = mkActionOption "visual tools" {
        command = "vicinae open || fuzzel";
        description = "Open visual tools";
      };
      fileManager = mkActionOption "file manager" {
        command = "xdg-open $HOME";
        description = "Open file manager";
      };
      editor = mkActionOption "editor" {
        command = "code";
        description = "Open editor";
      };
      fullscreen = mkActionOption "fullscreen" {
        description = "Toggle fullscreen";
      };
      logout = mkActionOption "logout/exit session" {
        description = "Exit compositor session";
      };
      closeWindow = mkActionOption "close window" {
        description = "Close focused window";
      };
      lock = mkActionOption "lock" {
        command = "loginctl lock-session";
        description = "Lock session";
      };
      screenshot = mkActionOption "screenshot" {
        command = ''grim -g "$(slurp)" - | wl-copy'';
        description = "Take a screenshot";
      };
    };
  };
}

{
  config,
  lib,
  pkgs,
  top,
  ...
}: let
  cfg = config.${top}.interface.backends.niri;

  inherit (lib.meta) getExe;
  inherit (lib.modules) mkIf;
in {
  config = mkIf (cfg.enable && (cfg.semanticKeybinds or false)) {
    home.packages = with pkgs; [
      (
        writeShellScriptBin "dots-common-keybinds" ''
          ${getExe libnotify} "Common desktop keybinds" "$(cat <<'HELP'
          Win+Space: secondary launcher
          Win+Enter: terminal
          Win+`: scratchpad terminal
          Win+B: primary browser
          Win+Alt+B: secondary browser
          Win+V: visual tools launcher
          Win+F: file manager
          Win+E: editor
          Alt+Enter / Win+Ctrl+F: fullscreen
          Win+Q: close focused window
          Win+Ctrl+L: lock session
          Win+Ctrl+Q: exit Niri
          Print: screenshot
          Win+Print: region screenshot to clipboard
          Win+Shift+/: Niri hotkey overlay
          HELP
          )"
        ''
      )
      brightnessctl
      grim
      libnotify
      slurp
      wl-clipboard
      wireplumber
    ];
  };
}

{lix, ...} @ args: let
  inherit (lix.modules) mkModules mkModuleArgs;
in
  mkModules (
    args
    // {
      base = ./.;
      excludes = [
        # "backend"
        "frontend"
        "protocol"
        "session"
      ];
      recurse = true;
      extraArgs = {
        mkArgs = {
          config,
          osConfig ? {},
          options ? {},
          path,
          scope ? "core",
          pkgs ? {},
        }:
          mkModuleArgs {
            inherit
              config
              options
              osConfig
              path
              pkgs
              scope
              ;
          };
      };
    }
  )

{
  mkChild,
  path,
  ...
}: let
  targets = [
    ["programs" "caelestia-shell"]
    ["programs" "caelestia"]
  ];
in {
  core = mkChild {
    inherit path targets;
  };

  home = mkChild {
    inherit path targets;
    scope = "home";
  };
}

{
  lix,
  mkChild,
  path,
  ...
}: let
  inherit (lix.attrsets) hasAttrByPath optionalAttrs;
  inherit (lix.options) mkEnableOption;
  inherit (lix.lists) elem;
  inherit (lix.types) isList isString;

  mkOptions = child: {
    isRequired =
      mkEnableOption "Whether this ${child.get.name} is selected by the host or user"
      // {
        default = let
          target = child.get.config.parent.selected;
        in
          if isList target
          then elem child.get.name target
          else if isString target
          then target == child.get.name
          else false;
      };

    needsNiri =
      mkEnableOption "Whether this ${child.get.name} is selected by the host or user"
      // {default = child.get.config.domain.backends.niri.enable or false;};
  };
in {
  core = mkChild {
    inherit path mkOptions;
    target = ["programs" "dms-shell"];
  };

  home = mkChild {
    inherit path mkOptions;
    scope = "home";
    target = ["programs" "dank-material-shell"];
    extraConfig = {
      config,
      cfg,
      enabled,
      options,
      ...
    }: let
      target = ["programs" "dank-material-shell" "niri"];
      targetExists = hasAttrByPath target options;
      includesEnable =
        if targetExists
        then config.programs.dank-material-shell.niri.includes.enable or true
        else true;
    in
      optionalAttrs targetExists {
        programs.dank-material-shell.niri = {
          enableKeybinds = enabled && (cfg.needsNiri or false) && !includesEnable;
          enableSpawn = enabled && (cfg.needsNiri or false);
        };
      };
  };
}

{
  lix,
  top,
  host,
  path,
  registry,
  selection,
  ...
} @ args: let
  inherit (lix.api) getInteractiveUsers;
  inherit (lix.attrsets) attrByPath namesOf valuesOf foldMerge hasAttr hasAttrByPath mapAttrs optionalAttrs recursiveUpdate setAttrByPath;
  inherit (lix.lists) elem elemAt filter findFirst length;
  inherit (lix.modules) mkDefault mkIf mkMerge mkModules;
  inherit (lix.options) mkEnable mkModuleArgs mkOption;
  inherit (lix.types) attrs enum nullOr package submodule;
  here = path;
  aliases = {
    dms = "dank-material";
  };
  frontendValues = [
    "dms"
    "dank-material"
    "noctalia"
    "caelestia"
    "gnome"
    "plasma"
    "cosmic"
  ];
  normalize = frontend:
    if frontend == null
    then null
    else aliases.${frontend} or frontend;
  registryFrontendOf = spec: let
    names = namesOf (selection spec);
    value =
      if length names > 0
      then elemAt names 0
      else null;
    env = optionalAttrs (value != null) (registry.${value} or {});
  in
    normalize (env.frontend or null);
  selectedFrontend = spec: normalize ((spec.interface or {}).frontend or (registryFrontendOf spec));
  materialize = selected:
    mapAttrs
    (_: extra: {enable = true;} // extra)
    (foldMerge (map (name: setAttrByPath [name] {}) (filter (name: name != null) selected)));
  required = let
    main = [
      (selectedFrontend host)
    ];
    isDesktopHost = elem (host.type or "desktop") ["desktop" "laptop"];
    userSelections =
      if isDesktopHost
      then map selectedFrontend (valuesOf (getInteractiveUsers host))
      else [];
  in {
    core = materialize (main ++ userSelections);
    home = user:
      materialize (
        main
        ++ (
          if isDesktopHost
          then [(selectedFrontend user)]
          else []
        )
      );
  };
  activeBackendNames = namesOf (selection host);
  primaryBackend =
    if length activeBackendNames > 0
    then elemAt activeBackendNames 0
    else null;
  primaryEnv =
    if primaryBackend != null
    then registry.${primaryBackend} or {}
    else {};
  registryFrontend = registryFrontendOf host;
  isWayland = primaryEnv.protocol or null == "wayland";
  mkMod = {
    config,
    options ? {},
    scope ? "core",
    pkgs,
    path ? here,
  }: let
    users = getInteractiveUsers host;
    module = mkModuleArgs {inherit top config path scope pkgs options users;};
    inherit (module.get) name prettyName;
    opt = module.set.options.module;
    fields = {
      enable = mkEnable {
        inherit name scope;
        default =
          if scope == "home"
          then hasAttr name (required.home module.user)
          else hasAttr name required.core;
      };
      package = mkOption {
        type = nullOr package;
        default = attrByPath [name] (attrByPath ["${name}-shell"] null pkgs) pkgs;
        description = "Package backing the ${prettyName} frontend layer.";
      };
    };
  in {
    inherit fields;
    args = {inherit module;};
    options = module.set.options.module fields;
    config = mkMerge [
      (opt {enable = mkDefault fields.enable.default;})
      (mkIf (fields.package.default != null) (opt {package = mkDefault fields.package.default;}))
    ];
  };
  inner = mkModules (args
    // {
      base = ./.;
      excludes = [];
      declareRegistry = false;
      childPath = path;
      extraArgs = let
        buildChild = {
          config,
          options ? {},
          path,
          pkgs ? {},
          scope ? "core",
          osConfig ? config,
          defaults ? {},
        }: let
          mod = mkMod {inherit config path pkgs scope options;};
          module = mod.args.module;
          cfgOr = key:
            attrByPath
            ([top] ++ path ++ [key]) (defaults.${key} or null)
            osConfig;
          enableTarget = {
            options,
            enabled,
            target ? null,
            targets ? [],
          }: let
            target' =
              if target != null && hasAttrByPath target options
              then target
              else findFirst (candidate: hasAttrByPath candidate options) null targets;
            hasSub = key: target' != null && hasAttrByPath (target' ++ [key]) options;
            frontendCfg = optionalAttrs (hasSub "enable") {enable = enabled;};
          in
            optionalAttrs (target' != null && frontendCfg != {}) (setAttrByPath target' frontendCfg);
        in
          module
          // {
            inherit cfgOr enableTarget;
            inherit (mod) options config;
          };
        mkChild = {
          path,
          scope ? "core",
          target ? null,
          targets ? [],
          mkOptions ? (_: {}),
          extraConfig ? (_: {}),
        }: {
          config,
          options,
          pkgs,
          ...
        }: let
          child = buildChild {inherit config options path pkgs scope;};
          cfg = child.get.config.module;
          enabled = cfg.enable or (cfg.isRequired or false);
          extraOptions = mkOptions child;
        in {
          options =
            if extraOptions == {}
            then child.options
            else recursiveUpdate child.options (child.set.options.module extraOptions);
          config = mkMerge [
            child.config
            (child.enableTarget {inherit options enabled target targets;})
            (extraConfig {inherit child cfg enabled config options pkgs;})
          ];
        };
      in {
        inherit mkChild;
        mkArgs = buildChild;
      };
    });
  mk = scope: {config, ...}: let
    mod = mkModuleArgs {
      inherit config top scope;
      path = ["interface"];
    };
    opt = mod.set.options.module;
    cfg = mod.get.config.module;
  in {
    options = opt {
      frontend = mkOption {
        type = submodule {
          freeformType = attrs;
          options.selected = mkOption {
            type = nullOr (enum frontendValues);
            apply = normalize;
            default = normalize (host.interface.frontend or registryFrontend);
            description = "Graphical frontend layer for the selected desktop session backend. `dms` is accepted as an alias for `dank-material`.";
          };
        };
        default = {};
        description = "Graphical frontend configuration.";
      };
    };
    config.assertions = [
      {
        assertion = cfg.frontend.selected == null || primaryBackend != null;
        message = "interface.frontend requires an active interface.backend.";
      }
      {
        assertion = cfg.frontend.selected == null || isWayland;
        message = "The selected interface.frontend requires a Wayland session.";
      }
      {
        assertion = cfg.frontend.selected == null || cfg.frontend.selected == registryFrontend;
        message = "interface.frontend.selected (${toString cfg.frontend.selected}) doesn't match the frontend the registry declares for '${toString primaryBackend}' (${toString registryFrontend}).";
      }
    ];
  };
in {
  core.imports = (inner.imports or []) ++ [(mk "core")];
  home.imports = (inner.home-manager.sharedModules or []) ++ [(mk "home")];
}

{
  mkChild,
  path,
  ...
}: {
  core = mkChild {
    inherit path;
    targets = [
      ["programs" "noctalia"]
      ["programs" "noctalia-shell"]
    ];
